const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const raw = String(source.rawText || source.text || source.query || args.query || args.eventId || message.text || payload.text || '').trim();
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const calendarId = source.calendarId || args.calendarId || payload.calendarId || 'primary';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D');
}
function pad(n) { return String(n).padStart(2, '0'); }
function iso(d, hour = d.getHours(), minute = d.getMinutes(), second = 0) {
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(hour)}:${pad(minute)}:${pad(second)}+07:00`;
}
function startOfDay(d) { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; }
function endOfDay(d) { const x = new Date(d); x.setHours(23, 59, 59, 0); return x; }
function addDays(base, days) { const d = new Date(base); d.setDate(d.getDate() + days); return d; }
function nextWeekday(base, targetDow, nextWeek = false) {
  const d = startOfDay(base);
  let diff = (targetDow - d.getDay() + 7) % 7;
  if (diff === 0) diff = 7;
  if (nextWeek) diff += 7;
  d.setDate(d.getDate() + diff);
  return d;
}

const text = normalize(source.text || source.query || args.query || raw);
const directEventId = String(source.eventId || args.eventId || '').trim();
const now = new Date();
let afterDate = now;
let beforeDate = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 30);

if (/hom nay/.test(text)) {
  afterDate = startOfDay(now);
  beforeDate = endOfDay(now);
} else if (/ngay mai|mai/.test(text)) {
  afterDate = startOfDay(addDays(now, 1));
  beforeDate = endOfDay(afterDate);
} else {
  const weekdayMatch = text.match(/thu\s*(2|3|4|5|6|7)|chu nhat/);
  if (weekdayMatch) {
    const targetDow = weekdayMatch[1] ? Number(weekdayMatch[1]) - 1 : 0;
    const targetDate = nextWeekday(now, targetDow, /tuan sau/.test(text));
    afterDate = startOfDay(targetDate);
    beforeDate = endOfDay(targetDate);
  }
}

const explicitQuery = String(source.query || args.query || '').trim();
const query = (explicitQuery || raw)
  .replace(/^(xoa lich|xóa lịch|huy lich|huỷ lịch|hủy lịch|xoa su kien|xóa sự kiện|huy su kien|hủy sự kiện|delete event|cancel event)\s*/i, '')
  .replace(/\b(hom nay|ngay mai|mai|ngay kia|tuan sau|tuan nay|cuoi tuan nay|cuoi tuan sau|thu\s*[2-7]|chu nhat)\b/gi, '')
  .replace(/\s+/g, ' ')
  .trim();
const hasDeleteQuery = Boolean(query);
const guidance = '🗑 <b>Xoá lịch</b>\n\nBạn hãy nói rõ tên lịch cần xoá, ví dụ:\n- xoá lịch họp team chiều mai\n- huỷ lịch gặp khách thứ 2\n- delete event demo sản phẩm';



// Stage 11 exact-id safety guard
const __stage11Pick = (...values) => {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'boolean') return value;
  }
  return '';
};
const __stage11Source = source || {};
const __stage11Args = args || __stage11Source.args || __stage11Source.payload?.args || {};
const __stage11Payload = typeof payload !== 'undefined' ? payload : (__stage11Source.payload || {});
const __stage11IdFields = ["eventId"];
const __stage11AlsoFields = [];
const __stage11HasId = Boolean(__stage11Pick(...__stage11IdFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11HasAlso = __stage11AlsoFields.length === 0 || Boolean(__stage11Pick(...__stage11AlsoFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11Allowed = __stage11HasId && __stage11HasAlso;
const __stage11Response = __stage11Allowed ? '' : "Mia chưa xoá lịch vì hành động này cần eventId cụ thể. Bạn hãy tìm lịch trước, chọn đúng sự kiện, rồi gửi lại kèm eventId nhé.";

return [{ json: { ...source, payload, message, rawText: raw, text, chatId, calendarId, directEventId, query: hasDeleteQuery ? query : '__missing_delete_target__', hasDeleteQuery: Boolean(hasDeleteQuery && __stage11Allowed), after: iso(afterDate, afterDate.getHours(), afterDate.getMinutes(), 0), before: iso(beforeDate, beforeDate.getHours(), beforeDate.getMinutes(), 59), response: __stage11Response ? __stage11Response : hasDeleteQuery || directEventId ? '' : guidance } }];

const source = $('Chuan Bi Xoa Lich').item.json;
if (source.directEventId) {
  return [{ json: { ...source, canDelete: true, eventId: source.directEventId, summary: source.query || 'Sự kiện đã chọn', start: '', end: '' } }];
}
if (!source.hasDeleteQuery) {
  return [{ json: { ...source, canDelete: false } }];
}
const rawData = $input.first().json || {};
const rows = (rawData.items || []).filter((event) => event && Object.keys(event).length > 0 && event.id);
const event = rows[0] || null;
if (!event || !event.id) {
  return [{ json: { ...source, canDelete: false, response: '⚠️ Không tìm thấy sự kiện phù hợp để xoá.' } }];
}
return [{
  json: {
    ...source,
    canDelete: true,
    eventId: event.id,
    summary: event.summary || 'Không có tiêu đề',
    start: event.start?.dateTime || event.start?.date || '',
    end: event.end?.dateTime || event.end?.date || ''
  }
}];

function toDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}
function formatDate(date) {
  return new Intl.DateTimeFormat('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: '2-digit', month: '2-digit', year: 'numeric' }).format(date);
}
function formatTime(date) {
  return new Intl.DateTimeFormat('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', minute: '2-digit', hour12: false }).format(date);
}
function formatRange(startValue, endValue) {
  const startDate = toDate(startValue);
  const endDate = toDate(endValue);
  if (!startDate) return startValue || '';
  if (!endDate) return `${formatTime(startDate)}, ${formatDate(startDate)}`;
  const sameDay = startDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' }) === endDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
  if (sameDay) return `${formatTime(startDate)} - ${formatTime(endDate)}, ${formatDate(startDate)}`;
  return `${formatTime(startDate)}, ${formatDate(startDate)} → ${formatTime(endDate)}, ${formatDate(endDate)}`;
}
const source = $('Chon Lich Can Xoa').item.json;
let text = '🗑 <b>Đã xoá lịch</b>\n\n';
text += `📝 <b>${source.summary}</b>\n`;
text += `🕒 ${formatRange(source.start, source.end)}`;
return [{ json: { chatId: source.chatId, text } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
